package com.hospital.dao;
import com.hospital.model.PaymentMethod;import com.hospital.util.DBConnection;import java.sql.*;import java.math.BigDecimal;
public class PaymentDAO {
 public void record(long bill,BigDecimal amount,PaymentMethod method,String ref,long user)throws SQLException{if(amount.signum()<=0)throw new IllegalArgumentException("Payment must be greater than zero.");try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{BigDecimal total,paid;try(PreparedStatement p=c.prepareStatement("SELECT total,paid_amount FROM bills WHERE bill_id=? FOR UPDATE")){p.setLong(1,bill);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Invoice not found.");total=r.getBigDecimal(1);paid=r.getBigDecimal(2);}}if(amount.compareTo(total.subtract(paid))>0)throw new SQLException("Payment exceeds the outstanding balance.");try(PreparedStatement p=c.prepareStatement("INSERT INTO payments(bill_id,amount,method,reference,created_by) VALUES(?,?,?,?,?)")){p.setLong(1,bill);p.setBigDecimal(2,amount);p.setString(3,method.name());p.setString(4,ref);p.setLong(5,user);p.executeUpdate();}BigDecimal newPaid=paid.add(amount);String status=newPaid.compareTo(total)==0?"PAID":"PARTIALLY_PAID";try(PreparedStatement p=c.prepareStatement("UPDATE bills SET paid_amount=?,status=? WHERE bill_id=?")){p.setBigDecimal(1,newPaid);p.setString(2,status);p.setLong(3,bill);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;throw new SQLException(e);}finally{c.setAutoCommit(true);}}}
}
